package org.example.defect.model;

import java.time.Instant;

import org.example.defect.Defect;
import org.example.defect.DefectPriority;
import org.example.defect.DefectStatus;

/**
 * A defect as returned by the API. Every field is always present; an optional field that was not
 * set is {@code null}.
 *
 * @param id        generated by the database
 * @param createdAt moment the defect was created (ISO-8601, UTC, microseconds)
 * @param updatedAt moment of the last change; equal to {@code createdAt} for a new defect
 */
public record DefectResponse(
        Long id,
        String title,
        String description,
        String stepsToReproduce,
        String expectedResult,
        String actualResult,
        DefectPriority priority,
        DefectStatus status,
        Instant createdAt,
        Instant updatedAt) {

    public static DefectResponse of(Defect defect) {
        return new DefectResponse(defect.getId(), defect.getTitle(), defect.getDescription(),
                defect.getStepsToReproduce(), defect.getExpectedResult(), defect.getActualResult(),
                defect.getPriority(), defect.getStatus(), defect.getCreatedAt(), defect.getUpdatedAt());
    }
}
